insert into public.products(id,name,status,base_price,promo_price,short_description,full_description,benefits,keywords,delivery_type,source,updated_at) values ('PS_DUNOKIDS','DunoKids','ACTIVE',159000,0,'DunoKids — produk resmi PRIME STORE','Bedakan masalah instalasi, kompatibilitas, jaringan internet, akses aplikasi, dan gangguan sumber tayangan.','Bedakan masalah instalasi, kompatibilitas, jaringan internet, akses aplikasi, dan gangguan sumber tayangan.',ARRAY['dunokids','duno kids'],'MANUAL','OWNER_PRIME_STORE',now()) on conflict(id) do update set name=excluded.name,status='ACTIVE',base_price=excluded.base_price,promo_price=0,short_description=excluded.short_description,full_description=excluded.full_description,benefits=excluded.benefits,keywords=excluded.keywords,demo_url=null,checkout_url=null,delivery_type=excluded.delivery_type,source=excluded.source,updated_at=now();
