insert into public.products(id,name,status,base_price,promo_price,short_description,full_description,benefits,keywords,delivery_type,source,updated_at) values ('PS_BUNDLE2','Bundling 2 Aplikasi','ACTIVE',118000,0,'Bundling 2 Aplikasi — produk resmi PRIME STORE','- Harga paket: Rp118.000.
- Pelanggan dapat memilih dua aplikasi sesuai pilihan yang diizinkan dalam katalog resmi.
- Sebelum mengonfirmasi pesanan, pastikan kedua aplikasi memang dapat dimasukkan dalam bundling tersebut.
- Jika pelanggan hanya berkata “paket dua aplikasi”, tanyakan dua aplikasi yang ingin dipilih.
- Jika pelanggan sudah menyebut kedua produk dengan jelas, jangan bertanya ulang.
- Setelah pembayaran diverifikasi, Admin akan menyiapkan akses kedua produk dan grup member yang relevan sesuai ketentuan paket.
- Jangan mengirim semua tautan aplikasi. Akses hanya untuk produk yang dipesan.','- Harga paket: Rp118.000.
- Pelanggan dapat memilih dua aplikasi sesuai pilihan yang diizinkan dalam katalog resmi.
- Sebelum mengonfirmasi pesanan, pastikan kedua aplikasi memang dapat dimasukkan dalam bundling tersebut.
- Jika pelanggan hanya berkata “paket dua aplikasi”, tanyakan dua aplikasi yang ingin dipilih.
- Jika pelanggan sudah menyebut kedua produk dengan jelas, jangan bertanya ulang.
- Setelah pembayaran diverifikasi, Admin akan menyiapkan akses kedua produk dan grup member yang relevan sesuai ketentuan paket.
- Jangan mengirim semua tautan aplikasi. Akses hanya untuk produk yang dipesan.',ARRAY['bundling','paket dua aplikasi','paket 2 aplikasi'],'MANUAL','OWNER_PRIME_STORE',now()) on conflict(id) do update set name=excluded.name,status='ACTIVE',base_price=excluded.base_price,promo_price=0,short_description=excluded.short_description,full_description=excluded.full_description,benefits=excluded.benefits,keywords=excluded.keywords,demo_url=null,checkout_url=null,delivery_type=excluded.delivery_type,source=excluded.source,updated_at=now();
insert into public.mc_runtime_knowledge(kind,source_key,payload,active)values('PRODUCT','PS_BUNDLE2','{"product_id": "PS_BUNDLE2", "product_name": "Bundling 2 Aplikasi", "price": 118000, "promo_price": null, "status": "ACTIVE", "description": "- Harga paket: Rp118.000.\n- Pelanggan dapat memilih dua aplikasi sesuai pilihan yang diizinkan dalam katalog resmi.\n- Sebelum mengonfirmasi pesanan, pastikan kedua aplikasi memang dapat dimasukkan dalam bundling tersebut.\n- Jika pelanggan hanya berkata “paket dua aplikasi”, tanyakan dua aplikasi yang ingin dipilih.\n- Jika pelanggan sudah menyebut kedua produk dengan jelas, jangan bertanya ulang.\n- Setelah pembayaran diverifikasi, Admin akan menyiapkan akses kedua produk dan grup member yang relevan sesuai ketentuan paket.\n- Jangan mengirim semua tautan aplikasi. Akses hanya untuk produk yang dipesan.", "full_description": "- Harga paket: Rp118.000.\n- Pelanggan dapat memilih dua aplikasi sesuai pilihan yang diizinkan dalam katalog resmi.\n- Sebelum mengonfirmasi pesanan, pastikan kedua aplikasi memang dapat dimasukkan dalam bundling tersebut.\n- Jika pelanggan hanya berkata “paket dua aplikasi”, tanyakan dua aplikasi yang ingin dipilih.\n- Jika pelanggan sudah menyebut kedua produk dengan jelas, jangan bertanya ulang.\n- Setelah pembayaran diverifikasi, Admin akan menyiapkan akses kedua produk dan grup member yang relevan sesuai ketentuan paket.\n- Jangan mengirim semua tautan aplikasi. Akses hanya untuk produk yang dipesan.", "aliases": ["bundling", "paket dua aplikasi", "paket 2 aplikasi"], "delivery": "MANUAL_ADMIN_WITHIN_2H_AFTER_VERIFICATION", "promo_status": "UNCONFIRMED", "source": "OWNER_PRIME_STORE"}'::jsonb,true) on conflict(kind,source_key)do update set payload=excluded.payload,active=true,synced_at=now();
